'use strict';
// Daily calculations use total plan capital once. Existing ledger entries are retained.
updateTariffMath=function(){const tier=demo.tariffs.find(t=>t.id===chosenTier);if(!tier||!$('#investment-amount'))return;investmentDraft=Number($('#investment-amount').value);const valid=Number.isFinite(investmentDraft)&&investmentDraft>=1&&investmentDraft<=1e7;$('#allocation-each').textContent=valid?money(investmentDraft/tier.count):'—';$('#allocation-payout').textContent=valid?money(investmentDraft*tier.rate/100):'—';if($('#scenario-results'))$('#scenario-results').innerHTML=[1,7,30].map(days=>`<div><span>${days} ${days===1?'day':'days'}</span><strong>${valid?money(investmentDraft*tier.rate/100*days):'—'}</strong><small>${(tier.rate*days).toFixed(1)}% of capital · simple demo accrual</small></div>`).join('');$('#tariff-error').textContent=valid?'':'Enter a total investment between $1 and $10,000,000.'};
sessionRows=function(){ensureTariffs();return demo.sessions.length?`<div class="table-scroll"><table><thead><tr><th>Demo event</th><th>Period</th><th>Capital basis</th><th>Rate</th><th>Accrual</th></tr></thead><tbody>${demo.sessions.slice().reverse().slice(0,30).map(s=>`<tr><td><strong>${s.period==='day'?'Daily simulation':'Legacy session simulation'}</strong><small>${escapeHtml(s.id)}</small></td><td>${s.period==='day'?escapeHtml(s.day):escapeHtml(s.city||'')+' · one session'}</td><td>${money(s.period==='day'?s.capital:s.allocatedCapital)}</td><td>${s.rate.toFixed(1)}% / ${s.period==='day'?'day':'session'}</td><td class="green-text">+${money(s.payout)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty-state">No demo accruals yet. Apply a plan, then simulate one day.</div>'};
actions['apply-plan']=()=>{const tier=demo.tariffs.find(t=>t.id===chosenTier);updateTariffMath();if(!Number.isFinite(investmentDraft)||investmentDraft<1||investmentDraft>1e7||Math.abs(investmentDraft*100-Math.round(investmentDraft*100))>.00001){$('#tariff-error').textContent='Enter a valid USD amount with no more than two decimal places.';return}if(chosenStations.length!==tier.count){$('#tariff-error').textContent=`Select exactly ${tier.count} charging stations.`;return}openModal(`<h2>Apply ${tier.name} demo plan?</h2><ul class="modal-list"><li><strong>Total simulated capital</strong><small>${money(investmentDraft)}</small></li><li><strong>Selected reference stations</strong><small>${tier.count} · ${money(investmentDraft/tier.count)} allocated to each</small></li><li><strong>Daily rate</strong><small>${tier.rate.toFixed(1)}% on total capital</small></li><li><strong>Daily demo accrual</strong><small>${money(investmentDraft*tier.rate/100)}</small></li></ul><div class="modal-note">No funds move. Previous demo accruals stay in the history. The new terms apply to future simulations.</div><button class="button primary" data-action="confirm-plan">Apply demo plan</button>`)};
actions['confirm-plan']=()=>{const tier=demo.tariffs.find(t=>t.id===chosenTier);demo.plan={tierId:tier.id,name:tier.name,rate:tier.rate,period:'day',capital:investmentDraft,stationIds:chosenStations.slice(),appliedAt:new Date().toISOString()};demo.portfolio=chosenStations.slice();activity(`${demo.client?.name||'Client'} applied ${tier.name}: ${tier.count} stations, ${tier.rate}% per demo day`);persist();$('#modal').close();renderMap();if(role==='admin')renderAdmin();else renderTariffs();toast('Daily demo plan applied. No real investment was made.')};
actions['simulate-session']=()=>{if(!demo.plan){toast('Apply a demo plan first.');return}const p=demo.plan,today=new Date().toISOString().slice(0,10);openModal(`<h2>Simulate one day</h2><p>Create one daily test accrual using the active plan. This is not a real payment or imported operating income.</p><form id="daily-accrual-form"><label for="accrual-day">Demo date</label><input id="accrual-day" type="date" value="${today}" required><div class="allocation-math"><div><span>Total capital</span><strong>${money(p.capital)}</strong></div><div><span>Daily demo rate</span><strong>${p.rate.toFixed(1)}%</strong></div><div class="allocation-total"><span>Demo credit for one day</span><strong>${money(p.capital*p.rate/100)}</strong></div></div><div class="modal-note">Simple accrual, no compounding. A date can be credited only once in this demo.</div><div class="form-error" id="daily-error" role="alert"></div><button class="button primary" type="submit">Create daily demo accrual</button></form>`)};
document.addEventListener('submit',e=>{if(e.target.id!=='daily-accrual-form')return;e.preventDefault();if(!demo.plan)return;const day=$('#accrual-day').value;if(!/^\d{4}-\d{2}-\d{2}$/.test(day)||Number.isNaN(Date.parse(day))){$('#daily-error').textContent='Choose a valid date.';return}if(demo.sessions.some(s=>s.period==='day'&&s.day===day)){$('#daily-error').textContent='This date already has a demo accrual. Choose another date.';return}const p=demo.plan,payout=Math.round(p.capital*p.rate)/100;demo.sessions.push({id:`DAY-${day}-${demo.sessions.length+1}`,period:'day',day,capital:p.capital,rate:p.rate,stationIds:p.stationIds.slice(),planName:p.name,payout,date:new Date().toISOString()});demo.balance=Math.round((demo.balance+payout)*100)/100;activity(`Daily demo accrual for ${day}: +${money(payout)} (${p.rate}% of ${money(p.capital)})`);persist();$('#modal').close();if(role==='admin')renderAdmin();else if(tab==='tariffs')renderTariffs();toast(`Daily demo accrual created: +${money(payout)}`)});
renderSessionWidget=function(){const card=$('.performance-card');let widget=$('#session-widget');if(!widget){card.querySelector('.card-heading').hidden=true;card.querySelector('.performance-body').hidden=true;widget=document.createElement('div');widget.id='session-widget';card.append(widget)}ensureTariffs();const p=demo.plan,capital=p?.capital||1000,rate=p?.rate||demo.tariffs[0].rate,last=demo.sessions.at(-1);widget.innerHTML=`<div class="session-heading"><h2>Daily accrual preview</h2><span class="simulation-badge">DEMO</span></div><div class="engine-location">${p?escapeHtml(p.name)+' plan':'Example allocation'} <span>· ${p?p.stationIds.length+' reference stations':'Choose a plan to begin'}</span></div><div class="engine-flow"><button class="engine-node" data-action="tariffs"><span>${icon('assets')}</span><small>${money(capital)} capital</small></button><div class="engine-connector"><i></i></div><button class="engine-node" data-action="tariffs"><span>${rate.toFixed(1)}<em>%</em></span><small>Daily demo rate</small></button><div class="engine-connector"><i></i></div><button class="engine-node payout-node" data-action="engine-details"><span>${money(capital*rate/100)}</span><small>Per demo day</small></button></div><div class="engine-bottom"><span>${last?'Last test: +'+money(last.payout)+' credited':'Simple accrual · no compounding'}</span><button data-action="${p?'simulate-session':'tariffs'}">${p?'Simulate day':'Choose plan'} ${icon('arrow')}</button></div>`};
actions['engine-details']=()=>{const p=demo.plan,capital=p?.capital||1000,rate=p?.rate||demo.tariffs[0].rate;openModal(`<h2>Daily demo calculation</h2><ol class="engine-explanation"><li><strong>Start with the total capital in the selected plan.</strong><span>${money(capital)} across ${p?.stationIds.length||1} reference station(s).</span></li><li><strong>Apply the daily rate once.</strong><span>${money(capital)} × ${rate.toFixed(1)}% = ${money(capital*rate/100)} per demo day.</span></li><li><strong>Simulate a date to record a test accrual.</strong><span>No compounding. Each date is credited once. The event is saved in the demo history.</span></li></ol><div class="modal-note">These are proposed demo rates, not verified investment returns. They are not derived from the listed stations' charging revenue.</div><button class="button primary" data-action="${p?'simulate-session':'tariffs'}">${p?'Simulate one day':'Choose a plan'}</button>`)};
actions.sessions=()=>openModal(`<h2>Demo accrual history</h2>${sessionRows()}<button class="button primary" data-action="${role==='admin'?'simulate-session':'tariffs'}">${role==='admin'?'Simulate a day':'Open plans & calculator'}</button>`);
const contractBeforeDaily=contractContent;
contractContent=function(){return contractBeforeDaily().replaceAll('per completed session','per day on total capital').replace('The displayed rate is applied to the capital allocated to the station.','The displayed daily rate is applied once to the total capital in the plan, without compounding.').replaceAll('distribution rules','daily calculation assumptions and distribution rules')};
const tariffAdminBeforeDaily=tariffAdmin;
tariffAdmin=function(){return tariffAdminBeforeDaily().replace('Capital is split equally.','Daily accrual uses total capital once. Reference allocation:').replace('per station.','per station.').replaceAll('Simulate a charging session','Simulate a day')};
const renderDailyPlanBar=renderPlanBar;
renderPlanBar=function(){renderDailyPlanBar();$('.metrics-grid .metric-card:last-child>span').textContent='Demo accruals';$('.metrics-grid .metric-card:last-child>strong').textContent=money(demo.sessions.reduce((sum,s)=>sum+s.payout,0));$('.metrics-grid .metric-card:last-child>small').textContent='Recorded test events';renderSessionWidget()};
renderSessionWidget();
